@chaunceyjiang

`thinking_token_budget: 100` is more than this model spends on that prompt, so it never binds and the transcript would look the same with or without it. Same request with a budget of 8:

**Before the patch:**

```console
curl -s localhost:11003/v1/chat/completions -H 'Content-Type: application/json' -d @- <<'JSON' | jq .
{"model":"muse","messages":[{"role":"user","content":"What's the weather like in Beijing?"}],"thinking_token_budget":8,"tools":[{"type":"function","strict":true,"function":{"name":"get_weather","description":"Get current weather for a city","parameters":{"type":"object","properties":{"city":{"type":"string"}},"required":["city"]}}}]}
JSON
{
  "error": {
    "message": "thinking_token_budget is set but reasoning_config is not configured. Please set --reasoning-parser and/or --reasoning-config to use thinking_token_budget.",
    "type": "BadRequestError",
    "param": null,
    "code": 400
  }
}
```

**After the patch:**

```console
curl -s localhost:11003/v1/chat/completions -H 'Content-Type: application/json' -d @- <<'JSON' | jq .
{"model":"muse","messages":[{"role":"user","content":"What's the weather like in Beijing?"}],"thinking_token_budget":8,"tools":[{"type":"function","strict":true,"function":{"name":"get_weather","description":"Get current weather for a city","parameters":{"type":"object","properties":{"city":{"type":"string"}},"required":["city"]}}}]}
JSON
{
  "id": "chatcmpl-97209a65b4443271",
  "object": "chat.completion",
  "created": 1788289160,
  "model": "muse",
  "choices": [
    {
      "index": 0,
      "message": {
        "role": "assistant",
        "content": null,
        "refusal": null,
        "annotations": null,
        "audio": null,
        "function_call": null,
        "tool_calls": [
          {
            "id": "chatcmpl-tool-b6f3d4cb3d2b6264",
            "type": "function",
            "function": {
              "name": "get_weather",
              "arguments": "{\"city\": \"Beijing\"}"
            }
          }
        ],
        "reasoning": "What's the weather like in Beijing? Use"
      },
      "logprobs": null,
      "finish_reason": "tool_calls",
      "stop_reason": 200008,
      "token_ids": null,
      "routed_experts": null
    }
  ],
  "service_tier": null,
  "system_fingerprint": "vllm-0.27.2rc1.dev116+gd4801990a-77d8df22",
  "usage": {
    "prompt_tokens": 402,
    "total_tokens": 460,
    "completion_tokens": 58,
    "prompt_tokens_details": null,
    "completion_tokens_details": {
      "reasoning_tokens": 0
    }
  },
  "prompt_logprobs": null,
  "prompt_token_ids": null,
  "prompt_text": null,
  "kv_transfer_params": null,
  "ec_transfer_params": null,
  "metrics": null
}
```

`usage.completion_tokens_details.reasoning_tokens` reads 0 there because counting is opt-in per parser and `muse_glimmer` does not implement `count_reasoning_tokens` yet. #54238 adds it.

Could you paste the actual outputs before and after the change?

```
Could you provide an actual before/after test comparison for this change?

For example, you could test it with something like:

```bash
curl http://localhost:8000/v1/chat/completions \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer EMPTY" \
  -d '{
    "model": "",
    "messages": [
      {
        "role": "user",
        "content": "What's the weather like in Beijing?"
      }
    ],
    "thinking_token_budget": 100,
    "tools": [
      {
        "type": "function",
        "strict": true,
        "function": {
          "name": "get_weather",
          "description": "Get current weather for a city",
          "parameters": {
            "type": "object",
            "properties": {
              "city": {
                "type": "string"
              }
            },
            "required": ["city"]
          }
        }
      }
    ]
  }'
```

